# Report and weights have separate switches so a small report download does not
# unexpectedly trigger a multi-gigabyte transfer. Both artifacts stay local/server-side.
DOWNLOAD_REPORT = True
DOWNLOAD_CHECKPOINT = False
if MODE == "train":
    checkpoint_archive = None
    if DOWNLOAD_CHECKPOINT:
        checkpoint_archive = Path(shutil.make_archive(str(run_directory / "checkpoint"), "zip", root_dir=checkpoint_directory))
    if IN_COLAB:
        from google.colab import files
        if DOWNLOAD_REPORT:
            files.download(str(report_archive))
        if checkpoint_archive is not None:
            files.download(str(checkpoint_archive))
    else:
        print("Download/copy the files from:", run_directory)
else:
    print("Inspection complete. No weights trained, no results invented, and no downloads requested.")
